cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define TILE 16
#define CIN 3
#define COUT 32
#define KH 3
#define KW 3

__global__ void conv2d_bf16_kernel(
    const __nv_bfloat16* __restrict__ x_ptr,
    const __nv_bfloat16* __restrict__ w_ptr,
    __nv_bfloat16* __restrict__ y_ptr,
    int N, int H, int W, int Ho, int Wo)
{
    __shared__ __nv_bfloat16 smem_x[CIN][TILE+KH-1][TILE+KW-1];
    __shared__ __nv_bfloat16 smem_w[COUT][CIN][KH][KW];

    int n = blockIdx.z;
    int oh_start = blockIdx.y * TILE;
    int ow_start = blockIdx.x * TILE;

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * TILE + tx;
    const int nthreads = TILE * TILE;

    // global tensors via cute
    Tensor gX = make_tensor(make_gmem_ptr(x_ptr),
        make_shape(N, CIN, H, W),
        make_stride(CIN * H * W, H * W, W, 1));
    Tensor gW = make_tensor(make_gmem_ptr(w_ptr),
        make_shape(COUT, CIN, KH, KW),
        make_stride(CIN * KH * KW, KH * KW, KW, 1));
    Tensor gY = make_tensor(make_gmem_ptr(y_ptr),
        make_shape(N, COUT, Ho, Wo),
        make_stride(COUT * Ho * Wo, Ho * Wo, Wo, 1));

    Tensor sX = make_tensor(make_smem_ptr(&smem_x[0][0][0]),
        make_shape(Int<CIN>{}, Int<TILE + KH - 1>{}, Int<TILE + KW - 1>{}),
        make_stride(Int<(TILE + KH - 1) * (TILE + KW - 1)>{}, Int<TILE + KW - 1>{}, Int<1>{}));
    Tensor sW = make_tensor(make_smem_ptr(&smem_w[0][0][0][0]),
        make_shape(Int<COUT>{}, Int<CIN>{}, Int<KH>{}, Int<KW>{}),
        make_stride(Int<CIN * KH * KW>{}, Int<KH * KW>{}, Int<KW>{}, Int<1>{}));

    // load weights cooperatively into shared memory
    const int wtotal = COUT * CIN * KH * KW;
    for (int idx = tid; idx < wtotal; idx += nthreads) {
        int kw = idx % KW;
        int rem1 = idx / KW;
        int kh = rem1 % KH;
        int rem2 = rem1 / KH;
        int ic = rem2 % CIN;
        int oc = rem2 / CIN;
        sW(oc, ic, kh, kw) = gW(oc, ic, kh, kw);
    }

    // load input tile cooperatively into shared memory
    const int TH = TILE + KH - 1;
    const int TW = TILE + KW - 1;
    const int xtotal = CIN * TH * TW;
    for (int idx = tid; idx < xtotal; idx += nthreads) {
        int c = idx % TW;
        int rem = idx / TW;
        int r = rem % TH;
        int ic = rem / TH;
        int gh = oh_start + r;
        int gw = ow_start + c;
        __nv_bfloat16 val = __float2bfloat16(0.0f);
        if (gh < H && gw < W) {
            val = gX(n, ic, gh, gw);
        }
        sX(ic, r, c) = val;
    }

    __syncthreads();

    int oh = oh_start + ty;
    int ow = ow_start + tx;
    if (oh < Ho && ow < Wo) {
        #pragma unroll
        for (int oc = 0; oc < COUT; ++oc) {
            float acc = 0.0f;
            #pragma unroll
            for (int ic = 0; ic < CIN; ++ic) {
                #pragma unroll
                for (int kh = 0; kh < KH; ++kh) {
                    #pragma unroll
                    for (int kw = 0; kw < KW; ++kw) {
                        float xv = __bfloat162float(sX(ic, ty + kh, tx + kw));
                        float wv = __bfloat162float(sW(oc, ic, kh, kw));
                        acc += xv * wv;
                    }
                }
            }
            gY(n, oc, oh, ow) = __float2bfloat16(acc);
        }
    }
}

torch::Tensor conv2d_cute(torch::Tensor x, torch::Tensor weight) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kBFloat16 && weight.scalar_type() == at::kBFloat16,
                "expect bf16 tensors");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D (Cout,Cin,KH,KW)");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);

    int Cout = (int)w_c.size(0);
    int Cin_w = (int)w_c.size(1);
    int Kh = (int)w_c.size(2);
    int Kw = (int)w_c.size(3);

    TORCH_CHECK(C == CIN && Cin_w == CIN, "expected in_channels == 3");
    TORCH_CHECK(Cout == COUT, "expected out_channels == 32");
    TORCH_CHECK(Kh == KH && Kw == KW, "expected kernel_size == 3");

    int Ho = H - KH + 1;
    int Wo = W - KW + 1;

    auto y = torch::empty({N, Cout, Ho, Wo}, x_c.options());

    dim3 block(TILE, TILE);
    dim3 grid((Wo + TILE - 1) / TILE, (Ho + TILE - 1) / TILE, N);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

